/// Day(t) = floor(t / msPerDay)
pub fn day(t: f64) -> f64 {
    (t / MS_PER_DAY).floor()
}

/// TimeWithinDay(t) = t modulo msPerDay (result in [0, msPerDay))
pub fn time_within_day(t: f64) -> f64 {
    let r = t % MS_PER_DAY;
    if r < 0.0 {
        r + MS_PER_DAY
    } else {
        r + 0.0
    }
}

