                }
                _ => return invalid(vm, "language", &code),
            };
            let c = t.base_name();
            let n = find(LANGUAGES, &c);
            (c, n)
        }
        "currency" => {
            if !(code.len() == 3 && code.bytes().all(|b| b.is_ascii_alphabetic())) {
                return invalid(vm, "currency", &code);
            }
            let c = code.to_ascii_uppercase();
            let n = find(CURRENCY_NAMES, &c);
            (c, n)
        }
